```python
def solution(s):
    lines = s.strip().split('\n')
    if not lines:
        return '0\n'

    n = int(lines[0])
    strings = lines[1:n+1]

    if n <= 1:
        return '0\n'

    from collections import Counter
    from itertools import combinations

    total = 0

    # Group strings by their sorted character tuple (canonical form)
    groups = {}
    for st in strings:
        key = tuple(sorted(st))
        if key not in groups:
            groups[key] = []
        groups[key].append(st)

    # Process each group
    for key, group in groups.items():
        m = len(group)

        # Strings with different canonical forms (different char counts)
        # They can never be made equal
        if len(group) > 1:
            # Count strings in this group
            cnt = Counter(group)
            for count in cnt.values():
                if count > 1:
                    # Identical strings in same group
                    pass  # 0 operations for identical

        # For anagrams (same key), check if 1 or 2 operations needed
        unique_strings = list(set(group))
        from collections import defaultdict
        same_key_groups = defaultdict(list)
        for st in group:
            same_key_groups[st].append(st)

        # Process each unique string in the group
        for i in range(len(unique_strings)):
            for j in range(i + 1, len(unique_strings)):
                s1 = unique_strings[i]
                s2 = unique_strings[j]

                # Check if s1 can be transformed to s2 in 1 operation
                if can_transform_in_1(s1, s2):
                    total += 1
                else:
                    # Need 2 operations
                    total += 2

    return f"{total}\n"

def can_transform_in_1(a, b):
    """Check if a can be transformed to b or b to a in 1 operation"""
    if a == b:
        return True

    # Check if character counts match
    if sorted(a) != sorted(b):
        return False

    n = len(a)
    # Check if sorting any substring of a gives b
    for i in range(n):
        for j in range(i + 1, n + 1):
            new_a = a[:i] + ''.join(sorted(a[i:j])) + a[j:]
            if new_a == b:
                return True

    # Check if sorting any substring of b gives a
    for i in range(n):
        for j in range(i + 1, n + 1):
            new_b = b[:i] + ''.join(sorted(b[i:j])) + b[j:]
            if new_b == a:
                return True

    return False
