import collections

def is_row_palindrome_reorderable(row):
    """Check if characters in row can form a palindrome"""
    count = collections.Counter(row)
    odd_count = sum(1 for v in count.values() if v % 2 != 0)
    return odd_count <= 1

def is_column_palindrome(col):
    """Check if a column is a palindrome"""
    return col == col[::-1]

def is_beautiful(submatrix):
    """Check if a submatrix is beautiful"""
    h = len(submatrix)
    if not submatrix:
        return False

    w = len(submatrix[0])

    # Every row must be reorderable as a palindrome
    for i in range(h):
        if not is_row_palindrome_reorderable(submatrix[i]):
            return False

    # Every column must be a palindrome
    for j in range(w):
        col = [submatrix[i][j] for i in range(h)]
        if not is_column_palindrome(col):
            return False

    return True

def solution(input_data):
