                                return "0\n"

                # Check bottom connection
                if props['bottom']:
                    if i == n-1:
                        pass  # OK at border
                    else:
                        down = cells[i+1][j]
                        if down != '.':
                            if not pipe_props[down]['top']:
                                return "0\n"

                # Check left connection
                if props['left']:
                    if j == 0:
                        pass  # OK at border
                    else:
                        left = cells[i][j-1]
                        if left != '.':
                            if not pipe_props[left]['right']:
                                return "0\n"

    count = 1
    for i in range(n):
        for j in range(m):
            if cells[i][j] == '.':
                valid = 0
                for t in ['1', '2', '3', '4']:
                    props = pipe_props[t]
                    ok = True

                    # Must match connections with neighbors
                    if props['top'] and i > 0:
                        up = cells[i-1][j]
                        if up != '.':
                            if not pipe_props[up]['bottom']:
                                ok = False

                    if props['left'] and j > 0:
                        left = cells[i][j-1]
                        if left != '.':
                            if not pipe_props[left]['right']:
                                ok = False

                    if props['bottom'] and i < n-1:
                        down = cells[i+1][j]
                        if down != '.':
                            if not pipe_props[down]['top']:
                                ok = False

                    if props['right'] and j < m-1:
                        right = cells[i][j+1]
                        if right != '.':
                            if not pipe_props[right]['left']:
                                ok = False

                    if ok:
                        valid += 1
                count = (count * valid) % MOD

    return f"{count}\n"
