        u = queue.popleft()
        for v, c in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)

    # Determine edge direction based on BFS distances
    # For edges between vertices at different distances, direct from closer to farther (away from source)
    # For edges at same distance, use vertex index as tiebreaker to maintain DAG property
    result = []
    for u, v, c in edges:
