            result.append('0')  # u is closer to source, edge goes u->v
        elif dist[v] < dist[u]:
            result.append('1')  # v is closer to source, edge goes v->u
        else:
            # Same distance - use vertex index as tiebreaker
            if u < v:
                result.append('0')  # u->v
            else:
                result.append('1')  # v->u

    return '\n'.join(result)
