def solution(input_string):
    n, r = map(int, input_string.strip().split())

    # Generate all valid points (integer coordinates within distance r from origin)
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x * x + y * y <= r * r:
                points.append((x, y))

    best_total = -1
    best_points = []

    # Brute force all combinations with replacement (since we can place multiple towers at same point)
    import itertools

    for combo in itertools.combinations_with_replacement(points, n):
        # Calculate sum of squared distances between all pairs
        total = 0
        for i in range(n):
            for j in range(i + 1, n):
                dx = combo[i][0] - combo[j][0]
                dy = combo[i][1] - combo[j][1]
                total += dx * dx + dy * dy

        if total > best_total:
            best_total = total
            best_points = combo

    # Format output
    output_lines = [str(best_total)]
    for x, y in best_points:
        output_lines.append(f"{x} {y}")

    return "\n".join(output_lines)
