        idx += n

        count = 0

        def check_axis_aligned(r, c, s):
            if s < 2:
                return False

            # Check frame (border) is all 1s
            # Top and bottom rows
            for j in range(c, c + s):
                if matrix[r][j] != '1' or matrix[r + s - 1][j] != '1':
                    return False
            # Left and right columns
            for i in range(r, r + s):
                if matrix[i][c] != '1' or matrix[i][c + s - 1] != '1':
                    return False

            # For size > 2, check interior is all 0s
            if s > 2:
                for i in range(r + 1, r + s - 1):
                    for j in range(c + 1, c + s - 1):
                        if matrix[i][j] != '0':
                            return False

            return True

        def check_rotated(center_r, center_c, s):
            if s < 2 or s % 2 == 0:
                return False

            d = (s - 1) // 2

            # Verify all four corners lie within bounds
            if (center_r - d < 0 or center_c - d < 0 or
                center_r + d >= n or center_c + d >= m):
                return False

            # Validate the diamond frame by checking positions around each corner
            for dc in range(-d, d + 1):
                for dr in range(-d, d + 1):
                    if dr == -d or dr == d or dc == -d or dc == d:
                        if matrix[center_r + dr][center_c + dc] != '1':
                            return False

            return True

        # Find axis-aligned squares
        for r in range(n):
            for c in range(m):
                for s in range(2, min(n - r, m - c) + 1):
                    if check_axis_aligned(r, c, s):
