Looking at this problem, I need to understand the mathematical properties of "Rotatable Numbers":

1. A rotatable number of length n in base b satisfies a special cyclic property
2. The key insight is that for a rotatable number to exist:
   - n+1 must be prime (related to the multiplicative order)
   - The base b must be such that b mod (n+1) is a primitive root modulo (n+1)

3. We need to find the largest b where 1 < b < x such that there exists a primitive root r mod (n+1) and b ≡ r (mod n+1)

```python
import sys

def is_prime(n):
    """Check if n is prime"""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def find_prime_factors(n):
    """Find all prime factors of n"""
    factors = []
    if n % 2 == 0:
        factors.append(2)
        while n % 2 == 0:
            n //= 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 2
    if n > 1:
        factors.append(n)
    return factors

def main():
    line = sys.stdin.readline()
    if not line:
        return
    n, x = map(int, line.strip().split())

    p = n + 1

    # n+1 must be prime
    if not is_prime(p):
        print(-1)
        return

    phi = p - 1

    # Find prime factors of phi
    prime_factors = find_prime_factors(phi)

    # Check each g in [2, p-1] to see if it's a primitive root
    def is_primitive_root(g, p, phi, prime_factors):
        # Must be in range [2, p-1]
        if g < 2 or g >= p:
            return False
        # Check that g^((p-1)/q) != 1 (mod p) for all prime factors q of p-1
        for q in prime_factors:
            if pow(g, phi // q, p) == 1:
                return False
        return True

    # Find all valid residues (primitive roots mod p)
    valid_residues = []
    for g in range(2, p):
        if is_primitive_root(g, p, phi, prime_factors):
            valid_residues.append(g)

    # Find the largest b < x such that b % p is in valid_residues
    max_b = -1
    for r in valid_residues:
        # Find largest b < x with b ≡ r (mod p)
        # Formula: b = (x-1) - ((x-1 - r) % p)
        b = (x - 1) - ((x - 1) - r) % p
        if b >= 2:  # Must satisfy 1 < b
            max_b = max(max_b, b)

    if max_b > -1:
        print(max_b)
    else:
        print(-1)

if __name__ == "__main__":
