def solution(input_string):
    """
    Solution function for finding the largest rotatable number base.

    Takes input as string "n x\n" and returns the result as string.
    """
    n, x = map(int, input_string.strip().split())

    p = n + 1

    # n+1 must be prime for a rotatable number to exist
    if not is_prime(p):
        return "-1\n"

    phi = p - 1

    # Find prime factors of phi
    def find_prime_factors(n):
        factors = []
        if n % 2 == 0:
            factors.append(2)
            while n % 2 == 0:
                n //= 2
        d = 3
        while d * d <= n:
            if n % d == 0:
                factors.append(d)
                while n % d == 0:
                    n //= d
            d += 2
        if n > 1:
            factors.append(n)
        return factors

    prime_factors = find_prime_factors(phi)

    # Check each g in [2, p-1] to see if it's a primitive root
    def is_primitive_root(g, p, phi, prime_factors):
        if g < 2 or g >= p:
            return False
        for q in prime_factors:
            if pow(g, phi // q, p) == 1:
                return False
        return True

    # Find all valid residues (primitive roots mod p)
    valid_residues = []
    for g in range(2, p):
        if is_primitive_root(g, p, phi, prime_factors):
            valid_residues.append(g)

    # Find the largest b < x such that b % p is in valid_residues
    max_b = -1
    for r in valid_residues:
        # Find largest b < x with b ≡ r (mod p)
        b = (x - 1) - ((x - 1) - r) % p
        if b >= 2:
            max_b = max(max_b, b)

    if max_b > -1:
        return f"{max_b}\n"
    else:
        return "-1\n"

