    else:
        return "-1"

    def simulate(pressed):
        """Return whether the configuration is valid (no counter equals a[i])"""
        for i in range(1, n + 1):
            val = pressed[i]
            val += sum(pressed[j] for j in adj[i])
            if val == a[i - 1]:
                return False
        return True

    # Try pressing all buttons
    all_pressed = [1] * (n + 1)
    if simulate(all_pressed):
        result = [i for i in range(1, n + 1)]
        return f"{len(result)}\n{' '.join(map(str, result))}"

    # Try pressing no buttons
    none_pressed = [0] * (n + 1)
    if simulate(none_pressed):
        result = []
        return f"{len(result)}\n"

    # Greedy: for each counter, if current value would equal a[i], press button
    pressed = [0] * (n + 1)
    for i in range(1, n + 1):
        val_without = sum(pressed[j] for j in adj[i])
        if val_without == a[i - 1]:
            pressed[i] = 1

    if simulate(pressed):
