                val = sum(pressed[j] for j in adj[i])
                if val == a[i - 1]:
                    valid_so_far = False
                    break
            else:
                val = pressed[i] + sum(pressed[j] for j in adj[i])
                if val == a[i - 1]:
                    valid_so_far = False
                    break

        if not valid_so_far:
            return False
           _ if idx > n else _try_press(idx)

    def _try_press(idx):
        nonlocal pressed

        # Don't press button at this counter
        pressed[idx] = 0
        valid = find_solution(idx + 1)
        if valid:
            return True

        # Try pressing button
        pressed[idx] = 1
        valid = find_solution(idx + 1)
