    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)

    a = list(map(int, lines[m + 1].split()))

    def simulate(pressed):
        for i in range(1, n + 1):
            val = pressed[i]
            val += sum(pressed[j] for j in adj[i])
            if val == a[i - 1]:
                return False
        return True

    # Try pressing all
    all_p = [1] * (n + 1)
    if simulate(all_p):
        res = [i for i in range(1, n + 1)]
        return f"{len(res)}\n{' '.join(map(str, res))}"

    # Try pressing none
    none_p = [0] * (n + 1)
    if simulate(none_p):
        return "0\n"

    # Greedy assignment
    pressed = [0] * (n + 1)
    for i in range(1, n + 1):
        without = sum(pressed[j] for j in adj[i])
        if without == a[i - 1]:
            pressed[i] = 1
        elif without == 0 and a[i - 1] == 0:
            pressed[i] = 1

    if simulate(pressed):
        res = [i for i in range(1, n + 1) if pressed[i]]
        return f"{len(res)}\n{' '.join(map(str, res))}"

    return "-1"
