    def get_primes(n):
        """Get prime factors of n using trial division"""
        primes = set()
        d = 2
        while d * d <= n:
            if n % d == 0:
                primes.add(d)
                while n % d == 0:
                    n //= d
            d += 1
        if n > 1:
            primes.add(n)
        return primes

    # Collect candidate primes from each element and neighbors
    candidates = set()
    for x in arr:
        for p in get_primes(x):
            candidates.add(p)
        for p in get_primes(x - 1):
            candidates.add(p)
        for p in get_primes(x + 1):
            candidates.add(p)

    ans = float('inf')

    def check_prime(p):
        """Check minimum cost for prime p using DP"""
        c = [0] * n
        for i in range(n):
            if arr[i] % p == 0:
                c[i] = 0
            else:
                if (arr[i] - 1) % p == 0 or (arr[i] + 1) % p == 0:
                    c[i] = 1
                else:
                    return float('inf')

        # DP: track minimum cost considering segment removal
        # dp[i] = minimum cost for prefix ending at i
        # We can either include element i or remove it
        dp = [0] * n
        dp[0] = c[0]

        for i in range(1, n):
            dp[i] = min(dp[i-1] + c[i], 2 * c[i])  # Either extend prefix or start new segment

        # Optionally remove entire array except one element
        for i in range(n):
            ans = min(ans, dp[i])

        # Check removing a middle segment (leaves prefix + suffix)
        prefix_min = 0
        for i in range(n):
            prefix_min = min(prefix_min + c[i], dp[i])

        # Consider removing segment from some i to j
        # Try removing [i:n] for each possible i
        local_ans = prefix_min

        for i in range(n):
            local_ans = min(local_ans, prefix_min + (dp[n-1] if i < n else 0))

        ans = min(ans, local_ans)

    # Check all candidate primes
    for p in candidates:
        if check_prime(p) < ans:
            pass

    # Also consider no removal (just fix all elements)
    if ans > float('inf'):
        ans = float('inf')

    # Compute cost without removal for each prime
    for p in candidates:
        cost = [0] * n
        for i in range(n):
            if arr[i] % p == 0:
                cost[i] = 0
            else:
                if (arr[i] - 1) % p == 0 or (arr[i] + 1) % p == 0:
                    cost[i] = 1
                else:
                    return float('inf')

        total = sum(cost)
        ans = min(ans, total)

    # Final: consider removing first segment to eliminate need for fixes
    if a < b:
        ans = min(ans, 1)  # Can remove single element

    return str(int(ans)) if ans != float('inf') else str(0)


