import sys

def solution(s):
    parts = s.strip().split()
    if len(parts) < 3:
        return "-1"
    maxx, maxy, w = int(parts[0]), int(parts[1]), int(parts[2])

    limit = max(maxx, maxy)
    rev_arr = [int(str(i)[::-1]) if i > 0 else 0 for i in range(limit + 1)]

    # lucky_grid[x][y] = 1 if pair (x, y) is lucky, else 0
    lucky_grid = [[0] * (maxy + 1) for _ in range(maxx + 1)]
    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            if x * y == rev_arr[x] * rev_arr[y]:
                lucky_grid[x][y] = 1

    # cum[x][y] = cumulative lucky count for 1..x × 1..y
    # This uses 2D prefix sum for efficient querying
    cum = [[0] * (maxy + 1) for _ in range(maxx + 1)]
    for x in range(1, maxx + 1):
        row_acc = 0
        for y in range(1, maxy + 1):
            row_acc += lucky_grid[x][y]
            cum[x][y] = cum[x-1][y] + row_acc

    # Find best (x, y) minimizing x * y
    best_x, best_y = -1, -1
    best_prod = float('inf')

    for x in range(1, maxx + 1):
