import math
from functools import lru_cache

def solution(input_str):
    parts = input_str.strip().split()
    if len(parts) != 2:
        return ''

    x, y = map(int, parts)

    if y == 0:
        return "0"

    # Special case: when x = 1, gcd(1, b) = 1, so we subtract 1 each time
    if x == 1:
        return str(y)

    @lru_cache(maxsize=None)
    def dp(b):
        if b == 0:
            return 0

        g = math.gcd(x, b)
        return 1 + dp(b - g)

    return str(dp(y))
