            if prev_r == 0:
                return 2

        # Build up from r-1 to get f_r(p^e)
        # f_r(p^e) = sum_{k=0}^e f_{r-1}(p^k)

        current = {}  # k -> f_{r-1}(p^k)

        for step in range(r):
            prev = current
            current = {}
            for k in range(120):  # Max exponent for primes <= 10^6 is 19, buffer for safety
                if k not in prev:
                    if step == 0:
                        prev_k = 1 if k == 0 else 2
                    else:
                        prev_k = sum(prev.get(i, 0) for i in range(k + 1)) % MOD
                    current[k] = prev_k
                else:
                    current[k] = (sum(prev.get(i, 0) for i in range(k + 1))) % MOD

        return current[e]

    results = []
    for r, n in queries:
        if n == 1:
            results.append("1")
            continue

        factors = n_factors[n]
        ans = 1

        for p, e in factors:
            val = compute_fr_pe(r, e)
            ans = (ans * val) % MOD

        results.append(str(ans))

    return '\n'.join(results)
