from collections import deque

def solution(input_str):
    """
    Solve the interactive grid navigation problem.

    Input contains:
    - Line 0: n m [swapLR] [swapUD]
    - Lines 1-n: grid rows

    Output: Sequence of button presses (U/D/L/R) to reach finish 'F'.
    """
    lines = input_str.strip().split('\n')

    # Parse n and m
    parts = lines[0].split()
    n = int(parts[0])
    m = int(parts[1])

    # Parse swap flags
    swapLR = int(parts[2]) if len(parts) > 2 else 0
    swapUD = int(parts[3]) if len(parts) > 3 else 0

    # Parse grid (n lines)
    grid = []
    for i in range(1, min(n + 1, len(lines))):
        grid.append(lines[i])

    # Find finish position
    finish_pos = None
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 'F':
                finish_pos = (r, c)
                break
        if finish_pos:
            break

    start_pos = (0, 0)  # (1,1) in problem is (0,0) in 0-indexed

    if not finish_pos:
        return ''

    # Create button mapping based on swaps
    def get_mappings(swapped_ud, swapped_lr):
        r_map = {'U': -1, 'D': 1}
        c_map = {'L': -1, 'R': 1}
        if swapped_ud:
            r_map = {'U': 1, 'D': -1}
        if swapped_lr:
            c_map = {'L': 1, 'R': -1}
        return r_map, c_map

    def bfs_find_path(r_map, c_map):
        """BFS to find shortest path from start to finish"""
        queue = deque([(0, 0, "")])  # (row, col, path)
        visited = {(0, 0)}

        while queue:
            r, c, path = queue.popleft()

            if (r, c) == finish_pos:
                return path

            for btn in ['U', 'D', 'L', 'R']:
                dr = r_map[btn]
                dc = c_map[btn]
                nr, nc = r + dr, c + dc

                if 0 <= nr < n and 0 <= nc < m and (nr, nc) not in visited:
                    if nr < len(grid) and nc < len(grid[nr]) and grid[nr][nc] != '*':
                        visited.add((nr, nc))
                        queue.append((nr, nc, path + btn))

        return None

    # Try with the given swap configuration first
    output = ''
    for su in [0, 1]:
        for sw in [0, 1]:
            r_map, c_map = get_mappings(su, sw)
            path = bfs_find_path(r_map, c_map)
            if path:
                return '\n'.join(path) + '\n'

    return ''
