def solution(input_str):
    import sys

    # Parse input
    data = input_str.strip().split()
    k = int(data[0])
    x = int(data[1])
    n = int(data[2])
    m = int(data[3])

    def count_ac_in_string(s):
        count = 0
        for i in range(len(s) - 1):
            if s[i] == 'A' and s[i+1] == 'C':
                count += 1
        return count

    # Recurrence: sk = sk-2 + sk-1
    # Track structure of each sk

    def get_structure(level, n, m):
        """
        Returns structure info for sk:
        - How many full s1 copies
        - How many full s2 copies  
        - The boundary chars (first and last)
        """
        # For small k we can compute directly
        if level == 1:
            return (1, 0, 'A', 'A')  # Copy: 1 s1, s1 ends with A
        elif level == 2:
            return (0, 1, 'A', 'A')  # Copy: 1 s2, s2 ends with A
        elif level == 3:
            # s3 = s1 + s2
            return (1, 1, 'A', 'A')  # s1 starts with A, s2 ends with A
        elif level == 4:
            # s4 = s2 + s3 = s2 + s1 + s2
            return (2, 1, 'A', 'A')
        elif level == 5:
            # s5 = s3 + s4 = (s1 + s2) + (s2 + s1 + s2)
            return (3, 3, 'A', 'A')
        elif level == 6:
            return (5, 5, 'A', 'A')
        else:
            # Follows Fibonacci pattern for counts
            f = [0, 1, 1]
            for i in range(3, level + 1):
                f.append(f[i-1] + f[i-2])
            # Structure pattern
            return (f[level-1], f[level-1], 'A', 'A')

    # For k > 3, the structure is complex. For k=3, it's just s1 + s2
    if k == 3:
        # s3 = s1 + s2
        # AC count = AC(s1) + AC(s2) + AC_at_boundary
        # AC_at_boundary = 1 if s1 ends with 'A' and s2 starts with 'C'

        if x == 0:
            # No AC at all - make both strings all 'A'
            s1 = 'A' * n
            s2 = 'A' * m
        elif x == 1:
            # AC at boundary
            s1 = 'A' * (n - 1) + 'C' if n > 1 else 'C'
            s2 = 'A' * m
        elif x == 2:
