            if n >= 3:
                # Put AC inside s1 and at boundary
                s1 = 'A' * (n - 2) + 'AC'  # Contains 1 AC
                s2 = 'C' * (m - 1) + 'AC' if m > 1 else 'AC'
            elif m >= 3:
                s1 = 'A' * n
                s2 = 'A' * (m - 2) + 'AC'
            else:
                # n=2, m=2, x=2 - s1=AC, s2=AC gives ACAC with 2 ACs
                s1 = 'AC'
                s2 = 'AC'
        elif x >= 3:
            # Put multiple AC patterns
            if n >= x:
                s1 = 'A' * (n - x) + 'AC' * x
                s2 = 'A' * m
            else:
                s1 = 'AC' * n
                s2 = 'AC' * x // 2
                if x % 2:
                    s2 = s2.rstrip('C') + 'AC'
        else:
            return "Happy new year!\n"

    elif k == 4:
        # s4 = s2 + s1 + s2
        # This is much more complex
        if x == 0:
            s1 = 'A' * n
            s2 = 'A' * m
        else:
            # Hard to construct exactly x
            if x == 1:
                s1 = 'A' * n
                s2 = 'C' + 'A' * (m - 1)  # Boundary gives AC
            elif x == 2:
                s1 = 'AC'
                s2 = 'A' * (m - 1) + 'AC'
                if m == 1:
                    s2 = 'AC'
            else:
                return "Happy new year!\n"
    elif k <= 5:
        # Try simple construction
        if x == 0:
            s1 = 'A' * n
            s2 = 'A' * m
        else:
            s1 = 'A' * (n - max(0, x-1))
            if s1 == '': s1 = 'A'
            s2 = ('C' + 'A') * (m - 1) + 'C' if m > 0 else 'C'
            # Adjust to get right x
            return "Happy new year!\n"
    else:
        # For k > 5, very hard to construct
        return "Happy new year!\n"

    return f"{s1}\n{s2}\n"


